scripts.眉儿对话.txt:
	If ($Event == 2034) @2034; // 从悲魔山庄来接紫轩
	Return;
	
@2034:
	Watch("紫轩","杨影枫",1);
	Say("月眉儿：杨大哥！你终于回来了。",23);
	Say("杨影枫：我在寒波谷找不到你们还以为你们出事了。",3);
	Say("月眉儿：我们在屋子里闷的很，便到跑这里来散散心。",23);
	Say("杨影枫：眉儿，你还好吧，伤势怎么样了？", 2);
	Say("月眉儿：我的伤势基本上好了，你见到真儿妹妹和蔷薇姑娘了吗？",23);
	Say("杨影枫：她们现在都在悲魔山庄等着我们过去呢。",3);
	Say("月眉儿：太好了，你是怎么把她们两个救出来的？",23);
	Say("杨影枫：说来话长……",2);
	FadeOut();
	Say("杨影枫给月眉儿和紫轩讲了事情的经过……");
	FadeIn();	
	Say("月眉儿：杨大哥，无忧教目前正在各处布下天罗地网，一定要制你于死地呢。",22);
	Say("杨影枫：如果让我碰上……就只能怪他们运气不好了。",6);
	Say("月眉儿：杨大哥，飞龙堡如今已经被无忧教占领了，我无家可归了，你带我一起走吧。",22);
	Say("杨影枫：我这次来就是这个意思……我想去忘忧岛归隐。",2);
	Say("紫轩：忘忧岛？那不是魔教的老巢吗？",16);
	Say("杨影枫：不错，那就是无忧教的发源地。",2);
	Say("紫轩：那不是等于自投罗网吗？",16);
	Say("月眉儿：不错，但是纳兰潜凛怎么也想不到我们又回了忘忧岛。",22);
	Say("紫轩：喔……",17);

	Watch("杨影枫","紫轩",0);
	Say("杨影枫：轩儿，你也跟我们一起走吧。",2);
	Say("紫轩：我……我还是留在寒波谷好了。",19);
	Say("杨影枫：为什么？",2);
	Say("紫轩：我……我的伤还没好，恐怕会拖累你们。",17);
	Say("杨影枫：怎么会？要走我们一起走，我不能让你一个人留在这儿。",2);
	Say("紫轩：我……我有点累先回去了……你们两个慢慢聊……",19);
	Say("杨影枫：紫轩……我们一会儿回去找你。",2);
	NpcGoto("紫轩",13,47);
	Watch("紫轩","杨影枫",1);
	Sleep(2000);
	NpcGoto("紫轩",13,55);
	DelNpc("紫轩");

	Watch("杨影枫","月眉儿",0);
	Say("月眉儿：杨大哥，想不到我爹一手创建的飞龙堡却毁在我的手里。",22);
	Say("杨影枫：你还想给你爹报仇吗？",3);
	Say("月眉儿：……我爹又不是我的亲爹……",22);
	Say("杨影枫：但是他毕竟对你有养育之恩。",2);
	Say("月眉儿：……其实最可怜的是我娘……",24);
	Say("杨影枫：都是我爹的错，他太看重天下第一这个名号了，结果害的你爹和你娘……",5);
	Say("月眉儿：难道你不想当天下第一吗？",22);
	Say("杨影枫：我已经厌烦了这些江湖上的名利之争，我只要有你就够了。",3);
	Say("月眉儿：哼……你真会讨女孩子的欢心，只怕你对真儿、蔷薇也是这么说的吧。",23);
	Say("杨影枫：我……眉儿……我对你是真心的。",2);
	Say("月眉儿：真的吗？那你肯为我而死吗？",23);
	Say("杨影枫：如果你不相信，那我……现在就死给你看……",3);
	Say("月眉儿：哼……你就知道我不舍得让你死。",22);
	Say("杨影枫：是呀……我死了，你怎么办呢？",3);
	Say("月眉儿：我……我不准你再胡说八道了。",22);
	Say("杨影枫：好吧，我不说了，但是你得让我抱一抱。",3);
	FadeOut();
	Say("说着……杨影枫把月眉儿抱进了怀里");
	Say("……良久……");
	FadeIn();
	Say("月眉儿：影枫……紫轩还在等我们呢……",22);
	Say("杨影枫：嗯……我们走吧。",2);
	SetNpcKind("月眉儿",3);
	Assign($Event, 2036);
	SetMapTrap(1,"trap01.txt");
	Return;

